"""Editorial multiplayer data. Times are session suggestions, not completion times."""
def game(id, name, genre, players, modes, minutes, description, note='', kind='Coopération', **extra):
    return dict(id=str(id), appid=id if isinstance(id,int) else None, name=name, genre=genre,
                minPlayers=players[0], maxPlayers=players[1], modes=modes, minutes=minutes,
                description=description, note=note, kind=kind, original=True,
                source=f'https://store.steampowered.com/app/{id}/' if isinstance(id,int) else 'https://store.steampowered.com/search/?term='+name.replace(' ','+'), **extra)

